@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Miami Heat DNA — heat culture black, vice flame gradient */
.theme-miami-heat {
  --bg: oklch(0.151 0.004 285.9);
  --surface: oklch(0.192 0.004 286.0);
  --surface-2: oklch(0.232 0.008 285.8);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.688 0.009 286.2);
  --accent: oklch(0.432 0.173 15.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.777 0.164 68.8);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-miami-heat h1,
.theme-miami-heat h2,
.theme-miami-heat h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-miami-heat { --font-ui: var(--font-display); }
.theme-miami-heat h1, .theme-miami-heat h2 { text-transform: uppercase; font-weight: 800; }
.theme-miami-heat button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-miami-heat { background-image: radial-gradient(ellipse at 50% 110%, oklch(0.55 0.2 25 / 35%), oklch(0.7 0.17 60 / 12%) 40%, transparent 70%); }
.theme-miami-heat h1 { background: linear-gradient(180deg, #ffffff, var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* depth */
.theme-miami-heat ::selection { background: var(--accent-2); color: oklch(0.151 0.004 285.9); }
.theme-miami-heat a { color: var(--accent-2); text-decoration-color: color-mix(in oklab, var(--accent) 70%, white); text-underline-offset: 3px; }
.theme-miami-heat a:hover { color: #ffffff; text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
/* flame rule under table heads */
.theme-miami-heat thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--fg-muted); background: oklch(0.13 0.004 286); border-bottom: 2px solid; border-image: linear-gradient(90deg, var(--accent), var(--accent-2)) 1; }
.theme-miami-heat td { border-bottom: 1px solid var(--line); }
.theme-miami-heat tbody tr:hover { background: oklch(0.55 0.20 25 / 10%); }
.theme-miami-heat input, .theme-miami-heat select, .theme-miami-heat textarea { background: oklch(0.125 0.004 286); border: 1px solid var(--line); caret-color: var(--accent-2); }
.theme-miami-heat input:focus-visible, .theme-miami-heat select:focus-visible, .theme-miami-heat textarea:focus-visible { outline: none; border-color: var(--accent-2); box-shadow: 0 0 0 1px var(--accent-2), 0 0 14px oklch(0.777 0.164 68.8 / 30%); }
.theme-miami-heat kbd { font-family: var(--font-mono); background: oklch(0.10 0.003 286); color: var(--accent-2); border: 1px solid oklch(0.55 0.14 45); border-radius: var(--radius-sm); padding: 0.1em 0.45em; }
.theme-miami-heat ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-miami-heat ::-webkit-scrollbar-track { background: oklch(0.125 0.004 286); }
.theme-miami-heat ::-webkit-scrollbar-thumb { background: linear-gradient(180deg, var(--accent-2), var(--accent)); border: 2px solid oklch(0.125 0.004 286); border-radius: 999px; }
.theme-miami-heat .label-caps { color: var(--accent-2); font-weight: 700; }
.theme-miami-heat .themed-border { border-color: oklch(0.55 0.16 30 / 60%); }
/* physical: ember — buttons heat up on hover, cool press on active */
.theme-miami-heat button:hover { box-shadow: 0 0 18px oklch(0.55 0.20 25 / 45%), 0 0 6px oklch(0.777 0.164 68.8 / 35%); }
.theme-miami-heat button:active { transform: translateY(1px); box-shadow: 0 0 6px oklch(0.55 0.20 25 / 30%); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-miami-heat.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.432 0.173 15.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.777 0.164 68.8);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-miami-heat.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #98002e; -webkit-text-stroke: 0; }
.theme-miami-heat.alt-mode input, .theme-miami-heat.alt-mode select, .theme-miami-heat.alt-mode textarea { background: #ffffff; border-color: var(--line); color: var(--fg); }
.theme-miami-heat.alt-mode a:hover { color: oklch(0.35 0.16 16); }
.theme-miami-heat.alt-mode thead th { color: oklch(0.85 0.01 286); }
.theme-miami-heat.alt-mode .label-caps { color: oklch(0.6 0.14 60); }
.theme-miami-heat.alt-mode ::-webkit-scrollbar-track { background: oklch(0.95 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
